package net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.TenantLoginProvider;
import net.civeira.phylax.feature.identity.tenantloginprovider.domain.valueobject.OidcDiscoveryUrlVO;

class OidcDiscoveryUrlValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of oidc discovery url of tenant login provider")
  void test_oidc_discovery_url_value_holder_assign_plain_value() {
    Object holder = new Object();
    OidcDiscoveryUrlValueHolder<Object> value = new OidcDiscoveryUrlValueHolder<>(holder);
    Assertions.assertSame(holder, value.oidcDiscoveryUrl("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcDiscoveryUrlValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals("one", value.getOidcDiscoveryUrl().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.oidcDiscoveryUrlNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getOidcDiscoveryUrlValue().isPresent(),
        "A null value object must be stored");
    Assertions.assertFalse(value.getOidcDiscoveryUrl().isPresent(),
        "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of oidc discovery url of tenant login provider")
  void test_oidc_discovery_url_value_holder_assign_value_object() {
    Object holder = new Object();
    OidcDiscoveryUrlValueHolder<Object> value = new OidcDiscoveryUrlValueHolder<>(holder);
    OidcDiscoveryUrlVO vo = OidcDiscoveryUrlVO.from("one");
    Assertions.assertFalse(value.getOidcDiscoveryUrlValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.oidcDiscoveryUrl(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getOidcDiscoveryUrlValue().orElseThrow());
    Assertions.assertSame(holder, value.oidcDiscoveryUrl(Optional.empty()));
    Assertions.assertFalse(value.getOidcDiscoveryUrlValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.oidcDiscoveryUrl(Optional.of(vo)));
    Assertions.assertSame(vo, value.getOidcDiscoveryUrlValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of oidc discovery url of tenant login provider against the original")
  void test_oidc_discovery_url_value_holder_read() {
    Object holder = new Object();
    OidcDiscoveryUrlValueHolder<Object> value = new OidcDiscoveryUrlValueHolder<>(holder);
    OidcDiscoveryUrlVO vo = OidcDiscoveryUrlVO.from("one");
    OidcDiscoveryUrlVO other = OidcDiscoveryUrlVO.from("one");
    TenantLoginProvider original = Mockito.mock(TenantLoginProvider.class);
    Mockito.when(original.getOidcDiscoveryUrlValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readOidcDiscoveryUrl(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readOidcDiscoveryUrl(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.oidcDiscoveryUrl(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readOidcDiscoveryUrl(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readOidcDiscoveryUrl(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of oidc discovery url of tenant login provider")
  void test_oidc_discovery_url_value_holder_unset() {
    Object holder = new Object();
    OidcDiscoveryUrlValueHolder<Object> value = new OidcDiscoveryUrlValueHolder<>(holder);
    OidcDiscoveryUrlVO vo = OidcDiscoveryUrlVO.from("one");
    value.oidcDiscoveryUrl(vo);
    Assertions.assertSame(holder, value.unsetOidcDiscoveryUrlIfMatches("oidcDiscoveryUrl_other"));
    Assertions.assertTrue(value.getOidcDiscoveryUrlValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetOidcDiscoveryUrlIfMatches("oidcDiscoveryUrl"));
    Assertions.assertFalse(value.getOidcDiscoveryUrlValue().isPresent(),
        "The field name must clear the value");
    value.oidcDiscoveryUrl(vo);
    Assertions.assertSame(holder, value.unsetOidcDiscoveryUrl());
    Assertions.assertFalse(value.getOidcDiscoveryUrlValue().isPresent(),
        "Unset must clear the value");
  }
}
